-- Empty database structure only. No records, identities, policies or source rows.
CREATE TABLE app_assessment_labels(assessment_id TEXT PRIMARY KEY,label TEXT NOT NULL);
CREATE TABLE app_column_maps(semester TEXT NOT NULL,header TEXT NOT NULL,mapping TEXT NOT NULL,PRIMARY KEY(semester,header));
CREATE TABLE app_imports(import_id TEXT PRIMARY KEY,kind TEXT NOT NULL,filename TEXT NOT NULL,semester TEXT,created_at TEXT NOT NULL,counts TEXT NOT NULL,status TEXT NOT NULL,backup_path TEXT NOT NULL,source_path TEXT,scope TEXT,sections TEXT);
CREATE TABLE app_instructors(semester TEXT NOT NULL,section TEXT NOT NULL,instructor TEXT NOT NULL,email TEXT,PRIMARY KEY(semester,section));
CREATE TABLE app_policies(semester TEXT PRIMARY KEY REFERENCES semesters(semester),policy_json TEXT NOT NULL);
CREATE TABLE app_proposals(ruid TEXT NOT NULL,semester TEXT NOT NULL,proposed_grade TEXT,source_import TEXT,PRIMARY KEY(ruid,semester),FOREIGN KEY(ruid,semester) REFERENCES enrollments(ruid,semester));
CREATE TABLE app_roster_events(import_id TEXT NOT NULL,ruid TEXT NOT NULL,semester TEXT NOT NULL,action TEXT NOT NULL,section TEXT,PRIMARY KEY(import_id,ruid,semester));
CREATE TABLE app_roster_state(ruid TEXT NOT NULL,semester TEXT NOT NULL,section TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(ruid,semester),FOREIGN KEY(ruid,semester) REFERENCES enrollments(ruid,semester));
CREATE TABLE app_score_cells(ruid TEXT NOT NULL,semester TEXT NOT NULL,assessment_id TEXT NOT NULL,column_key TEXT NOT NULL,percent REAL,status TEXT NOT NULL,raw_id INTEGER NOT NULL,role TEXT NOT NULL,header TEXT NOT NULL,source_id INTEGER NOT NULL,PRIMARY KEY(ruid,semester,assessment_id,column_key));
CREATE TABLE app_section_observations(observation_id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES sources(source_id),source_row INTEGER NOT NULL,kind TEXT NOT NULL,semester TEXT NOT NULL,ruid TEXT,netid TEXT,section TEXT NOT NULL,UNIQUE(source_id,source_row,kind));
CREATE TABLE app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE app_teacher_people(instructor_id TEXT PRIMARY KEY,name TEXT NOT NULL,profile_url TEXT);
CREATE TABLE app_teaching_assignments(semester TEXT NOT NULL,section TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('lecturer','recitation')),instructor_id TEXT NOT NULL REFERENCES app_teacher_people(instructor_id),raw_name TEXT NOT NULL,source_url TEXT,source_section TEXT,source_kind TEXT NOT NULL DEFAULT 'schedule',email TEXT,PRIMARY KEY(semester,section,role,instructor_id));
CREATE TABLE app_teaching_overrides(semester TEXT NOT NULL,section TEXT NOT NULL,role TEXT NOT NULL,PRIMARY KEY(semester,section,role));
CREATE TABLE app_teaching_sources(semester TEXT PRIMARY KEY,url TEXT NOT NULL,sha256 TEXT NOT NULL,fetched TEXT NOT NULL,issues TEXT NOT NULL);
CREATE TABLE assessment_definitions(assessment_id TEXT PRIMARY KEY,semester TEXT NOT NULL REFERENCES semesters(semester),assessment_key TEXT NOT NULL,assessment_type TEXT NOT NULL,weight_percent REAL NOT NULL,policy TEXT NOT NULL,UNIQUE(semester,assessment_key));
CREATE TABLE assessment_scores(ruid TEXT NOT NULL,semester TEXT NOT NULL,assessment_id TEXT NOT NULL REFERENCES assessment_definitions(assessment_id),percent REAL,status TEXT NOT NULL,selection_rule TEXT NOT NULL,selected_raw_ids TEXT NOT NULL,source_id INTEGER REFERENCES sources(source_id),dropped_from_average INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(ruid,semester,assessment_id),FOREIGN KEY(ruid,semester) REFERENCES enrollments(ruid,semester));
CREATE TABLE average_observations(average_id INTEGER PRIMARY KEY,ruid TEXT NOT NULL,semester TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES sources(source_id),source_row INTEGER,kind TEXT NOT NULL,value REAL,FOREIGN KEY(ruid,semester) REFERENCES enrollments(ruid,semester));
CREATE TABLE average_validations(ruid TEXT NOT NULL,semester TEXT NOT NULL,comparison_kind TEXT NOT NULL,reference_average REAL,calculated_average REAL,difference REAL,result TEXT NOT NULL,PRIMARY KEY(ruid,semester,comparison_kind),FOREIGN KEY(ruid,semester) REFERENCES enrollments(ruid,semester));
CREATE TABLE calculation_variants(ruid TEXT NOT NULL,semester TEXT NOT NULL,variant TEXT NOT NULL,value REAL,policy TEXT NOT NULL,PRIMARY KEY(ruid,semester,variant),FOREIGN KEY(ruid,semester) REFERENCES enrollments(ruid,semester));
CREATE TABLE canvas_observations(canvas_row_id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES sources(source_id),source_row INTEGER NOT NULL,semester TEXT NOT NULL REFERENCES semesters(semester),ruid TEXT REFERENCES students(ruid),canvas_id TEXT,name TEXT,netid TEXT,match_status TEXT NOT NULL,final_score REAL,current_score REAL,unposted_final_score REAL,UNIQUE(source_id,source_row));
CREATE TABLE enrollments(ruid TEXT NOT NULL REFERENCES students(ruid),semester TEXT NOT NULL REFERENCES semesters(semester),name TEXT NOT NULL,netid TEXT,unit TEXT,class TEXT,curric TEXT,official_grade TEXT,course_average REAL,saved_course_average REAL,calculated_course_average REAL,average_status TEXT NOT NULL DEFAULT 'not_available',roster_status TEXT NOT NULL,grade_source_id INTEGER REFERENCES sources(source_id),average_source_id INTEGER REFERENCES sources(source_id),PRIMARY KEY(ruid,semester),CHECK(official_grade IS NULL OR official_grade NOT IN ('TF','TTZ')),CHECK(official_grade IS NULL OR official_grade<>'W' OR course_average IS NULL));
CREATE TABLE field_provenance(ruid TEXT NOT NULL,semester TEXT NOT NULL,field TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES sources(source_id),source_row INTEGER,PRIMARY KEY(ruid,semester,field),FOREIGN KEY(ruid,semester) REFERENCES enrollments(ruid,semester));
CREATE TABLE identity_aliases(netid TEXT NOT NULL,ruid TEXT NOT NULL REFERENCES students(ruid),semester TEXT NOT NULL REFERENCES semesters(semester),source_id INTEGER NOT NULL REFERENCES sources(source_id),PRIMARY KEY(netid,ruid,semester,source_id));
CREATE TABLE import_runs(import_id INTEGER PRIMARY KEY,started_at TEXT NOT NULL,completed_at TEXT,status TEXT NOT NULL,input_manifest_hash TEXT NOT NULL UNIQUE);
CREATE TABLE input_columns(input_id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES sources(source_id),column_number INTEGER NOT NULL,excel_column TEXT NOT NULL,exact_header TEXT NOT NULL,points_possible REAL,assessment_id TEXT REFERENCES assessment_definitions(assessment_id),role TEXT NOT NULL,UNIQUE(source_id,column_number));
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE raw_scores(raw_score_id INTEGER PRIMARY KEY,canvas_row_id INTEGER NOT NULL REFERENCES canvas_observations(canvas_row_id),input_id INTEGER NOT NULL REFERENCES input_columns(input_id),raw_value TEXT,status TEXT NOT NULL,points REAL,percent REAL,UNIQUE(canvas_row_id,input_id));
CREATE TABLE resolution_decisions(decision_id INTEGER PRIMARY KEY,created_at TEXT NOT NULL,rule TEXT NOT NULL,affected_records INTEGER NOT NULL);
CREATE TABLE review_issues(issue_id INTEGER PRIMARY KEY,ruid TEXT,semester TEXT,assessment_id TEXT,kind TEXT NOT NULL,details TEXT NOT NULL,source_id INTEGER REFERENCES sources(source_id), resolution_status TEXT NOT NULL DEFAULT 'open', resolution_note TEXT);
CREATE TABLE roster_observations(observation_id INTEGER PRIMARY KEY,ruid TEXT NOT NULL REFERENCES students(ruid),semester TEXT NOT NULL REFERENCES semesters(semester),source_id INTEGER NOT NULL REFERENCES sources(source_id),source_row INTEGER,name TEXT,netid TEXT,unit TEXT,class TEXT,curric TEXT,raw_grade TEXT,normalized_grade TEXT,saved_average REAL);
CREATE TABLE semesters(semester TEXT PRIMARY KEY,year INTEGER NOT NULL,season TEXT NOT NULL,status TEXT NOT NULL,policy_json TEXT NOT NULL);
CREATE TABLE sources(source_id INTEGER PRIMARY KEY,kind TEXT NOT NULL,semester TEXT,file_name TEXT NOT NULL,original_path TEXT NOT NULL,sha256 TEXT NOT NULL,source_date TEXT NOT NULL,imported_at TEXT NOT NULL,UNIQUE(kind,original_path,sha256));
CREATE TABLE students(ruid TEXT PRIMARY KEY CHECK(length(ruid)=9 AND ruid NOT GLOB '*[^0-9]*'));
CREATE INDEX app_roster_active ON app_roster_state(semester,section,active);
CREATE INDEX app_teaching_lookup ON app_teaching_assignments(semester,section,role,instructor_id);
CREATE INDEX enrollment_grades ON enrollments(semester,official_grade);
CREATE INDEX enrollment_names ON enrollments(name COLLATE NOCASE);
CREATE INDEX enrollment_netids ON enrollments(netid COLLATE NOCASE);
CREATE INDEX raw_inputs ON raw_scores(input_id,canvas_row_id);
CREATE VIEW assessment_statistics AS SELECT d.semester,d.assessment_id,d.assessment_key,d.weight_percent,COUNT(s.percent) AS scored_students,AVG(s.percent) AS mean_percent,MIN(s.percent) AS minimum_percent,MAX(s.percent) AS maximum_percent,AVG(s.percent*s.percent)-AVG(s.percent)*AVG(s.percent) AS population_variance,COUNT(s.ruid)-COUNT(s.percent) AS missing_or_excused FROM assessment_definitions d LEFT JOIN assessment_scores s USING(assessment_id) GROUP BY d.assessment_id;
CREATE VIEW exam_distributions AS SELECT s.semester,s.assessment_id,CAST(s.percent/10 AS INTEGER)*10 AS bin_lower_percent,COUNT(*) AS students FROM assessment_scores s JOIN assessment_definitions d USING(assessment_id) WHERE d.assessment_type IN ('midterm','final','precalculus','readiness') AND s.percent IS NOT NULL GROUP BY s.assessment_id,CAST(s.percent/10 AS INTEGER)*10;
CREATE VIEW grade_distributions AS SELECT semester,official_grade AS grade,COUNT(*) AS students,100.0*COUNT(*)/(SELECT COUNT(*) FROM enrollments b WHERE b.semester=a.semester AND b.official_grade IS NOT NULL) AS percent_of_graded, (SELECT COUNT(*) FROM enrollments b WHERE b.semester=a.semester) AS roster_count FROM enrollments a WHERE official_grade IS NOT NULL GROUP BY semester,official_grade;
CREATE VIEW open_review_issues AS SELECT * FROM review_issues WHERE resolution_status='open';
CREATE VIEW records AS SELECT name,ruid,netid,semester,official_grade AS grade,course_average,unit,class,curric FROM enrollments;
CREATE VIEW semester_summary AS SELECT semester,COUNT(*) AS records,COUNT(official_grade) AS with_grade,COUNT(*)-COUNT(official_grade) AS pending_grade,COUNT(course_average) AS with_average,COUNT(calculated_course_average) AS reconstructed_averages,SUM(average_status IN ('verified','verified_rounding')) AS verified_averages,SUM(average_status LIKE '%review%') AS averages_needing_review FROM enrollments GROUP BY semester;
